#include "optimizer_loop_internal.h"

#include "ir_helpers.h"

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Run two linear range iterations per condition check when the trip
// count is exact.
void optimizer_loop_store_induction(Ctx* ctx,
                                    IrFunctionId fid,
                                    IrBlockId block,
                                    IrStackSlotId slot,
                                    IrOperand value) {
  ir_add_instruction(
      ctx, fid, block,
      (IrInstruction){.type = IR_INST_STORE,
                      .operands.store = {.source = value, .target = slot}});
}

void optimizer_loop_unroll_range_by_two(Ctx* ctx,
                                        IrFunctionId fid,
                                        IrBlockId pre,
                                        const RangeBody* body,
                                        IrValueId induction,
                                        IrStackSlotId slot,
                                        IrInt start,
                                        IrInt step,
                                        uint64_t count,
                                        IrValueId next) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  size_t original_values = fn->value_count;

  if (count % 2 != 0) {
    size_t offset = fn->value_count;

    optimizer_loop_clone_iteration_block(
        ctx, fid, pre, body->blocks[0], body, induction, slot,
        (IrOperand){IR_OP_INT32, {.int32_value = start}}, offset);

    fn->value_count = offset + original_values;

    optimizer_loop_store_induction(
        ctx, fid, pre, slot,
        (IrOperand){IR_OP_INT32, {.int32_value = start + step}});
  }

  size_t offset = fn->value_count;
  IrOperand current = {IR_OP_VALUE, {.id = next}};

  optimizer_loop_clone_iteration_block(ctx, fid, body->latch, body->blocks[0],
                                       body, induction, slot, current, offset);

  fn->value_count = offset + original_values;

  IrValueId advanced = ir_add_instruction(
      ctx, fid, body->latch,
      (IrInstruction){.type = IR_INST_ADD,
                      .result_type = IR_INT,
                      .operands.binary = {
                          .left = current,
                          .right = {IR_OP_INT32, {.int32_value = step}},
                      }});

  optimizer_loop_store_induction(ctx, fid, body->latch, slot,
                                 (IrOperand){IR_OP_VALUE, {.id = advanced}});
}

// Recognize a sum of induction values so a closed-form result can replace the
// backedge.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Fold a constant integer accumulation after proving every
// intermediate fits.
bool optimizer_loop_fold_range_sum(Ctx* ctx,
                                   IrFunctionId fid,
                                   IrBlockId pre_id,
                                   const RangeBody* body,
                                   IrBlockId exit,
                                   IrValueId induction,
                                   IrStackSlotId iterator,
                                   IrInt start,
                                   IrInt step,
                                   uint64_t trips,
                                   IrInt final) {
  if (!trips || trips > 65536 || body->count != 1)
    return false;

  IrFunction* fn = &ctx->ir.functions.data[fid];
  const IrInstructionArray* instructions =
      &fn->blocks.data[body->blocks[0]].instructions;

  if (instructions->count < 3 || instructions->count > 4)
    return false;

  const IrInstruction* add = &instructions->data[instructions->count - 2];
  const IrInstruction* store = &instructions->data[instructions->count - 1];

  if (add->type != IR_INST_ADD || add->result_type != IR_INT ||
      store->type != IR_INST_STORE ||
      store->operands.store.target == iterator ||
      !optimizer_loop_direct_use(store->operands.store.source, add->result))
    return false;

  IrStackSlotId accumulator = store->operands.store.target;
  IrValueId total_id = IR_INVALID_ID;
  IrValueId term_id = induction;

  for (size_t i = 0; i < instructions->count - 2; i++) {
    const IrInstruction* load = &instructions->data[i];

    if (load->type != IR_INST_LOAD || load->result == IR_INVALID_ID)
      return false;

    if (load->operands.load.source == accumulator)
      total_id = load->result;
    else if (load->operands.load.source == iterator)
      term_id = load->result;
    else
      return false;
  }

  IrOperand left = add->operands.binary.left;
  IrOperand right = add->operands.binary.right;

  if (total_id == IR_INVALID_ID ||
      !((optimizer_loop_direct_use(left, total_id) &&
         optimizer_loop_direct_use(right, term_id)) ||
        (optimizer_loop_direct_use(left, term_id) &&
         optimizer_loop_direct_use(right, total_id))))
    return false;

  const IrInstructionArray* pre = &fn->blocks.data[pre_id].instructions;
  const IrOperand* initial = NULL;

  for (size_t i = 0; i < pre->count; i++)
    if (pre->data[i].type == IR_INST_STORE &&
        pre->data[i].operands.store.target == accumulator)
      initial = &pre->data[i].operands.store.source;

  if (!initial || initial->type != IR_OP_INT32 ||
      initial->value.int32_value < INT32_MIN ||
      initial->value.int32_value > INT32_MAX)
    return false;

  IrInt sum = initial->value.int32_value;
  IrInt current = start;

  for (uint64_t trip = 0; trip < trips; trip++) {
    sum += current;

    if (sum < INT32_MIN || sum > INT32_MAX)
      return false;

    current += step;
  }

  optimizer_loop_store_induction(
      ctx, fid, pre_id, accumulator,
      (IrOperand){IR_OP_INT32, {.int32_value = sum}});

  optimizer_loop_store_induction(
      ctx, fid, pre_id, iterator,
      (IrOperand){IR_OP_INT32, {.int32_value = final}});

  ir_set_terminator(ctx, fid, pre_id,
                    (IrBlockTerminator){.type = IR_TERMINATOR_JUMP,
                                        .value.jump_target = exit});
  return true;
}
